//! App manifest → Kubernetes objects. Pure: no I/O, no randomness (secret values are
//! generated by the installer and only placed into [`secret_object`]).
//!
//! Per app: Namespace `app-<name>` (labelled `melissa.io/app=<name>`, Pod Security
//! `baseline` enforced), a RoleBinding that gives the `melissa-apps` ServiceAccount the
//! `melissa-app-workload` role in that namespace only, a Secret with the generated secrets,
//! one PVC per volume (`local-path`), a single-replica Deployment with the `Recreate`
//! strategy, a ClusterIP Service and a Traefik Ingress for `<name>.<domain>`.

use std::collections::BTreeMap;

use k8s_openapi::{
    api::{
        apps::v1::{Deployment, DeploymentSpec, DeploymentStrategy},
        core::v1::{
            Container, ContainerPort, EnvVar, EnvVarSource, HTTPGetAction, HTTPHeader, Namespace,
            PersistentVolumeClaim, PersistentVolumeClaimSpec, PersistentVolumeClaimVolumeSource,
            PodSecurityContext, PodSpec, PodTemplateSpec, Probe, ResourceRequirements,
            SeccompProfile, Secret, SecretKeySelector, Service, ServicePort, ServiceSpec, Volume,
            VolumeMount, VolumeResourceRequirements,
        },
        networking::v1::{
            HTTPIngressPath, HTTPIngressRuleValue, Ingress, IngressBackend, IngressRule,
            IngressServiceBackend, IngressSpec, ServiceBackendPort,
        },
        rbac::v1::{RoleBinding, RoleRef, Subject},
    },
    apimachinery::pkg::{
        api::resource::Quantity, apis::meta::v1::LabelSelector, util::intstr::IntOrString,
    },
};
use kube::api::ObjectMeta;
use melissa_agent::tools::Owner;
use melissa_catalog::{Builtin, EnvSource, Manifest, ResolvedConfig};

/// Label on every object of an app (and the namespace): the app's name.
pub const APP_LABEL: &str = "melissa.io/app";
/// Field manager for server-side apply.
pub const FIELD_MANAGER: &str = "melissa";
/// The write identity (see `image/rootfs/usr/lib/melissa/k3s/manifests/apps-rbac.yaml`).
pub const APPS_SERVICE_ACCOUNT: &str = "melissa-apps";
pub const MELISSA_NAMESPACE: &str = "melissa";
/// ClusterRole bound per app namespace for [`APPS_SERVICE_ACCOUNT`].
pub const WORKLOAD_ROLE: &str = "melissa-app-workload";
/// Cell labels on the app's namespace (docs/HIVE-MODEL.md): the cell's name, the comb it is
/// on and the bee that owns it. `melissa.io/cell` and `melissa.io/comb` are set at the first
/// install; `melissa.io/owner-bee` is set at the first install (absent: unassigned) and
/// changed only by the reassign path together with fresh `assigned-*` annotations (admission
/// policy `melissa-apps-namespaces`).
pub const CELL_LABEL: &str = "melissa.io/cell";
pub const COMB_LABEL: &str = "melissa.io/comb";
pub const OWNER_BEE_LABEL: &str = "melissa.io/owner-bee";
/// Who gave the cell to its bee (`the Queen, approved by the user`, `the user`, `bee Ada
/// (…) (task 7)` for a cell a bee created) and when (RFC 3339, sub-second).
pub const ASSIGNED_BY_ANNOTATION: &str = "melissa.io/assigned-by";
pub const ASSIGNED_AT_ANNOTATION: &str = "melissa.io/assigned-at";
/// The owner label from before bees (`owner` or `job-<key>`). Read for migration only: such
/// a cell counts as unassigned and loses the label at its next install or reassignment.
pub const LEGACY_OWNER_LABEL: &str = "melissa.io/owner";
/// Annotations on the app's namespace, set at the first install and kept: who installed it
/// (`the user`, `the Queen (task 3)`, `bee Ada (c-….b1) (task 7)`), when (RFC 3339), and
/// from where (`catalog`).
pub const INSTALLED_BY_ANNOTATION: &str = "melissa.io/installed-by";
pub const INSTALLED_AT_ANNOTATION: &str = "melissa.io/installed-at";
pub const ORIGIN_ANNOTATION: &str = "melissa.io/origin";
/// Annotation on the Deployment: the resolved, non-secret config as JSON.
pub const CONFIG_ANNOTATION: &str = "melissa.io/config";
/// Pod Security Standard enforced in app namespaces. `baseline` forbids privileged pods,
/// host namespaces and hostPath volumes, so the write identity can't reach the node.
pub const POD_SECURITY_LEVEL: &str = "baseline";
pub const STORAGE_CLASS: &str = "local-path";
pub const INGRESS_CLASS: &str = "traefik";

/// Everything one install applies, in apply order.
#[derive(Debug, Clone, PartialEq)]
pub struct AppObjects {
    pub namespace: Namespace,
    pub role_binding: RoleBinding,
    /// Generated secrets, if the app declares any. Created once, never overwritten.
    pub secret: Option<SecretPlan>,
    pub volumes: Vec<PersistentVolumeClaim>,
    pub deployment: Deployment,
    pub service: Option<Service>,
    pub ingress: Option<Ingress>,
}

/// What [`secret_object`] needs besides the values.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SecretPlan {
    pub namespace: String,
    pub name: String,
    /// Key → generated length.
    pub keys: BTreeMap<String, usize>,
    pub labels: BTreeMap<String, String>,
}

fn labels(m: &Manifest) -> BTreeMap<String, String> {
    BTreeMap::from([
        (APP_LABEL.into(), m.name.clone()),
        ("app.kubernetes.io/name".into(), m.name.clone()),
        ("app.kubernetes.io/version".into(), label_value(&m.version)),
        ("app.kubernetes.io/managed-by".into(), "melissa".into()),
    ])
}

/// Label values: at most 63 of `[A-Za-z0-9._-]`, alphanumeric at both ends.
fn label_value(s: &str) -> String {
    let cleaned: String = s
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-') {
                c
            } else {
                '_'
            }
        })
        .take(63)
        .collect();
    cleaned
        .trim_matches(|c: char| !c.is_ascii_alphanumeric())
        .to_string()
}

fn meta(m: &Manifest, name: &str) -> ObjectMeta {
    ObjectMeta {
        name: Some(name.into()),
        namespace: Some(m.namespace()),
        labels: Some(labels(m)),
        ..ObjectMeta::default()
    }
}

/// A cell's record on its namespace: which comb and bee, and how it got here.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Ownership {
    /// The comb id (None on a namespace from before combs had ids; set at the next install).
    pub comb: Option<String>,
    /// The owning bee (`Unassigned`: no `melissa.io/owner-bee` label).
    pub owner: Owner,
    pub assigned_by: Option<String>,
    pub assigned_at: Option<String>,
    pub installed_by: String,
    pub installed_at: String,
    pub origin: String,
    /// `melissa.io/owner` from before bees, if still there.
    pub legacy_owner: Option<String>,
}

impl Ownership {
    /// The record on an existing namespace. Namespaces from before bees have no owner-bee
    /// label: they are unassigned (only the Queen with the user's approval, or the user,
    /// may change them); unknown annotations stay `unknown`.
    pub fn of(ns: &Namespace) -> Self {
        let label = |k: &str| ns.metadata.labels.as_ref().and_then(|l| l.get(k)).cloned();
        let ann = |k: &str| {
            ns.metadata
                .annotations
                .as_ref()
                .and_then(|a| a.get(k))
                .cloned()
        };
        let unknown = |v: Option<String>| v.unwrap_or_else(|| "unknown".into());
        Self {
            comb: label(COMB_LABEL),
            owner: Owner::from_label(label(OWNER_BEE_LABEL).as_deref()),
            assigned_by: ann(ASSIGNED_BY_ANNOTATION),
            assigned_at: ann(ASSIGNED_AT_ANNOTATION),
            installed_by: unknown(ann(INSTALLED_BY_ANNOTATION)),
            installed_at: unknown(ann(INSTALLED_AT_ANNOTATION)),
            origin: unknown(ann(ORIGIN_ANNOTATION)),
            legacy_owner: label(LEGACY_OWNER_LABEL),
        }
    }

    /// Put the record on a rendered namespace for cell `cell`. The legacy owner label is not
    /// written again, so a reinstall migrates the namespace to the cell labels.
    pub fn apply_to(&self, cell: &str, ns: &mut Namespace) {
        let labels = ns.metadata.labels.get_or_insert_with(BTreeMap::new);
        labels.insert(CELL_LABEL.into(), cell.into());
        if let Some(comb) = &self.comb {
            labels.insert(COMB_LABEL.into(), comb.clone());
        }
        if let Some(bee) = self.owner.label_value() {
            labels.insert(OWNER_BEE_LABEL.into(), bee.into());
        }
        let annotations = ns.metadata.annotations.get_or_insert_with(BTreeMap::new);
        if let (Some(by), Some(at)) = (&self.assigned_by, &self.assigned_at) {
            annotations.insert(ASSIGNED_BY_ANNOTATION.into(), by.clone());
            annotations.insert(ASSIGNED_AT_ANNOTATION.into(), at.clone());
        }
        annotations.insert(INSTALLED_BY_ANNOTATION.into(), self.installed_by.clone());
        annotations.insert(INSTALLED_AT_ANNOTATION.into(), self.installed_at.clone());
        annotations.insert(ORIGIN_ANNOTATION.into(), self.origin.clone());
    }
}

/// The merge patch that gives cell `cell` on comb `comb` to bee `bee` (the reassign path):
/// new owner label, fresh `assigned-*` annotations (the admission policy requires them for
/// an owner change), and the legacy owner label removed.
pub fn assign_patch(cell: &str, comb: &str, bee: &str, by: &str, at: &str) -> serde_json::Value {
    serde_json::json!({
        "metadata": {
            "labels": {
                CELL_LABEL: cell,
                COMB_LABEL: comb,
                OWNER_BEE_LABEL: bee,
                LEGACY_OWNER_LABEL: null,
            },
            "annotations": {
                ASSIGNED_BY_ANNOTATION: by,
                ASSIGNED_AT_ANNOTATION: at,
            },
        }
    })
}

/// Render `manifest` with resolved `config` for ingress domain `domain`.
pub fn render(manifest: &Manifest, config: &ResolvedConfig, domain: &str) -> AppObjects {
    let m = manifest;
    let ns = m.namespace();
    let host = m.host(domain);
    let selector = BTreeMap::from([(APP_LABEL.to_string(), m.name.clone())]);

    let mut ns_labels = BTreeMap::from([
        (APP_LABEL.to_string(), m.name.clone()),
        ("melissa.io/managed".into(), "true".into()),
        (
            "pod-security.kubernetes.io/enforce".into(),
            POD_SECURITY_LEVEL.into(),
        ),
        (
            "pod-security.kubernetes.io/enforce-version".into(),
            "latest".into(),
        ),
    ]);
    ns_labels.insert("app.kubernetes.io/managed-by".into(), "melissa".into());
    let namespace = Namespace {
        metadata: ObjectMeta {
            name: Some(ns.clone()),
            labels: Some(ns_labels),
            ..ObjectMeta::default()
        },
        ..Namespace::default()
    };

    let role_binding = RoleBinding {
        metadata: meta(m, APPS_SERVICE_ACCOUNT),
        role_ref: RoleRef {
            api_group: Some("rbac.authorization.k8s.io".into()),
            kind: "ClusterRole".into(),
            name: WORKLOAD_ROLE.into(),
        },
        subjects: Some(vec![Subject {
            kind: "ServiceAccount".into(),
            name: APPS_SERVICE_ACCOUNT.into(),
            namespace: Some(MELISSA_NAMESPACE.into()),
            api_group: None,
        }]),
    };

    let secret = (!config.secrets.is_empty()).then(|| SecretPlan {
        namespace: ns.clone(),
        name: m.secret_name(),
        keys: config.secrets.clone(),
        labels: labels(m),
    });

    let volumes = m
        .volumes
        .iter()
        .map(|v| PersistentVolumeClaim {
            metadata: meta(m, &pvc_name(m, &v.name)),
            spec: Some(PersistentVolumeClaimSpec {
                access_modes: Some(vec!["ReadWriteOnce".into()]),
                storage_class_name: Some(STORAGE_CLASS.into()),
                resources: Some(VolumeResourceRequirements {
                    requests: Some(BTreeMap::from([(
                        "storage".into(),
                        Quantity(v.size.clone()),
                    )])),
                    ..VolumeResourceRequirements::default()
                }),
                ..PersistentVolumeClaimSpec::default()
            }),
            ..PersistentVolumeClaim::default()
        })
        .collect();

    let containers = m
        .containers
        .iter()
        .map(|c| container(m, c, config, &host))
        .collect();
    let pod_volumes: Vec<Volume> = m
        .volumes
        .iter()
        .map(|v| Volume {
            name: v.name.clone(),
            persistent_volume_claim: Some(PersistentVolumeClaimVolumeSource {
                claim_name: pvc_name(m, &v.name),
                read_only: None,
            }),
            ..Volume::default()
        })
        .collect();

    let mut deploy_meta = meta(m, &m.name);
    // BTreeMap → JSON object with sorted keys; serializing a map of strings can't fail.
    let config_json = serde_json::to_string(&config.values).unwrap_or_default();
    deploy_meta.annotations = Some(BTreeMap::from([(
        CONFIG_ANNOTATION.to_string(),
        config_json,
    )]));
    let deployment = Deployment {
        metadata: deploy_meta,
        spec: DeploymentSpec {
            replicas: Some(1),
            revision_history_limit: Some(3),
            // One pod owns the ReadWriteOnce volume; never run old and new at once.
            strategy: Some(DeploymentStrategy {
                type_: Some("Recreate".into()),
                rolling_update: None,
            }),
            selector: LabelSelector {
                match_labels: Some(selector.clone()),
                match_expressions: None,
            },
            template: PodTemplateSpec {
                metadata: Some(ObjectMeta {
                    labels: Some(labels(m)),
                    ..ObjectMeta::default()
                }),
                spec: Some(PodSpec {
                    containers,
                    volumes: (!pod_volumes.is_empty()).then_some(pod_volumes),
                    // Apps never talk to the Kubernetes API.
                    automount_service_account_token: Some(false),
                    // No `<SERVICE>_PORT=tcp://...` variables colliding with app settings.
                    enable_service_links: Some(false),
                    security_context: Some(PodSecurityContext {
                        seccomp_profile: Some(SeccompProfile {
                            type_: "RuntimeDefault".into(),
                            localhost_profile: None,
                        }),
                        ..PodSecurityContext::default()
                    }),
                    ..PodSpec::default()
                }),
            },
            ..DeploymentSpec::default()
        },
        ..Deployment::default()
    };

    let ports: Vec<ServicePort> = m
        .containers
        .iter()
        .flat_map(|c| &c.ports)
        .map(|p| ServicePort {
            name: Some(p.name.clone()),
            port: i32::from(p.port),
            target_port: Some(IntOrString::String(p.name.clone())),
            protocol: Some("TCP".into()),
            ..ServicePort::default()
        })
        .collect();
    let service = (!ports.is_empty()).then(|| Service {
        metadata: meta(m, &m.name),
        spec: Some(ServiceSpec {
            type_: Some("ClusterIP".into()),
            selector: Some(selector.clone()),
            ports: Some(ports),
            ..ServiceSpec::default()
        }),
        ..Service::default()
    });

    let ingress = m.ingress.as_ref().map(|i| Ingress {
        metadata: meta(m, &m.name),
        spec: Some(IngressSpec {
            ingress_class_name: Some(INGRESS_CLASS.into()),
            rules: Some(vec![IngressRule {
                host: Some(host.clone()),
                http: Some(HTTPIngressRuleValue {
                    paths: vec![HTTPIngressPath {
                        path: Some("/".into()),
                        path_type: "Prefix".into(),
                        backend: IngressBackend {
                            service: Some(IngressServiceBackend {
                                name: m.name.clone(),
                                port: Some(ServiceBackendPort {
                                    name: Some(i.port.clone()),
                                    number: None,
                                }),
                            }),
                            resource: None,
                        },
                    }],
                }),
            }]),
            ..IngressSpec::default()
        }),
        ..Ingress::default()
    });

    AppObjects {
        namespace,
        role_binding,
        secret,
        volumes,
        deployment,
        service,
        ingress,
    }
}

/// PVC name for volume `volume` of app `m`.
pub fn pvc_name(m: &Manifest, volume: &str) -> String {
    format!("{}-{volume}", m.name)
}

fn container(
    m: &Manifest,
    c: &melissa_catalog::Container,
    config: &ResolvedConfig,
    host: &str,
) -> Container {
    let env: Vec<EnvVar> = c
        .env
        .iter()
        .filter_map(|(name, value)| {
            // Validation guarantees exactly one source; skip defensively otherwise.
            let source = value.source()?;
            let (value, value_from) = match source {
                EnvSource::Value(v) => (Some(v.to_string()), None),
                EnvSource::Config(f) => (config.values.get(f).map(|v| v.to_env()), None),
                EnvSource::Builtin(Builtin::IngressHost) => (Some(host.to_string()), None),
                EnvSource::Builtin(Builtin::IngressUrl) => (Some(format!("http://{host}")), None),
                EnvSource::Secret(f) => (
                    None,
                    Some(EnvVarSource {
                        secret_key_ref: Some(SecretKeySelector {
                            name: m.secret_name(),
                            key: f.to_string(),
                            optional: Some(false),
                        }),
                        ..EnvVarSource::default()
                    }),
                ),
            };
            Some(EnvVar {
                name: name.clone(),
                value,
                value_from,
            })
        })
        .collect();
    let r = &c.resources;
    let quantities = |cpu: &str, mem: &str| {
        BTreeMap::from([
            ("cpu".to_string(), Quantity(cpu.into())),
            ("memory".to_string(), Quantity(mem.into())),
        ])
    };
    let probe = c.probe.as_ref().map(|p| {
        let http_get = HTTPGetAction {
            path: Some(p.path.clone()),
            port: IntOrString::String(p.port.clone()),
            http_headers: p.ingress_host_header.then(|| {
                vec![HTTPHeader {
                    name: "Host".into(),
                    value: host.to_string(),
                }]
            }),
            ..HTTPGetAction::default()
        };
        let period = i32::try_from(p.period_secs).unwrap_or(10);
        let startup_failures =
            i32::try_from(p.startup_timeout_secs.div_ceil(p.period_secs.max(1))).unwrap_or(30);
        let base = Probe {
            http_get: Some(http_get),
            timeout_seconds: Some(5),
            ..Probe::default()
        };
        (
            // Startup: give the first start (installers, migrations) its full time.
            Probe {
                period_seconds: Some(period),
                failure_threshold: Some(startup_failures.max(1)),
                ..base.clone()
            },
            Probe {
                period_seconds: Some(period),
                failure_threshold: Some(3),
                ..base.clone()
            },
            // Liveness: restart only after a sustained failure (about two minutes).
            Probe {
                period_seconds: Some(30),
                timeout_seconds: Some(10),
                failure_threshold: Some(4),
                ..base
            },
        )
    });
    let (startup_probe, readiness_probe, liveness_probe) = match probe {
        Some((s, r, l)) => (Some(s), Some(r), Some(l)),
        None => (None, None, None),
    };
    Container {
        name: c.name.clone(),
        image: Some(c.image.clone()),
        image_pull_policy: Some("IfNotPresent".into()),
        ports: (!c.ports.is_empty()).then(|| {
            c.ports
                .iter()
                .map(|p| ContainerPort {
                    name: Some(p.name.clone()),
                    container_port: i32::from(p.port),
                    protocol: Some("TCP".into()),
                    ..ContainerPort::default()
                })
                .collect()
        }),
        env: (!env.is_empty()).then_some(env),
        volume_mounts: (!c.mounts.is_empty()).then(|| {
            c.mounts
                .iter()
                .map(|mnt| VolumeMount {
                    name: mnt.volume.clone(),
                    mount_path: mnt.path.clone(),
                    ..VolumeMount::default()
                })
                .collect()
        }),
        resources: Some(ResourceRequirements {
            requests: Some(quantities(&r.cpu_request, &r.memory_request)),
            limits: Some(quantities(&r.cpu_limit, &r.memory_limit)),
            ..ResourceRequirements::default()
        }),
        startup_probe,
        readiness_probe,
        liveness_probe,
        ..Container::default()
    }
}

/// The Secret for `plan` with generated `values` (key → value). Keys not in `values` are
/// left out (the caller generates all of them).
pub fn secret_object(plan: &SecretPlan, values: BTreeMap<String, String>) -> Secret {
    Secret {
        metadata: ObjectMeta {
            name: Some(plan.name.clone()),
            namespace: Some(plan.namespace.clone()),
            labels: Some(plan.labels.clone()),
            ..ObjectMeta::default()
        },
        type_: Some("Opaque".into()),
        string_data: Some(values),
        ..Secret::default()
    }
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use serde_json::{json, Value};

    use super::*;

    fn nextcloud() -> Manifest {
        Manifest::parse(include_str!("../../../manifests/nextcloud.toml")).unwrap()
    }

    /// All objects as one JSON document (what the golden file holds).
    fn as_json(o: &AppObjects) -> Value {
        json!({
            "namespace": o.namespace,
            "role_binding": o.role_binding,
            "secret": o.secret.as_ref().map(|p| json!({
                "namespace": p.namespace, "name": p.name, "keys": p.keys, "labels": p.labels,
            })),
            "volumes": o.volumes,
            "deployment": o.deployment,
            "service": o.service,
            "ingress": o.ingress,
        })
    }

    /// Compare with `tests/golden/<name>.json`; `MELISSA_UPDATE_GOLDEN=1` rewrites it.
    fn golden(name: &str, actual: &Value) {
        let path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/golden")
            .join(format!("{name}.json"));
        let text = serde_json::to_string_pretty(actual).unwrap() + "\n";
        if std::env::var_os("MELISSA_UPDATE_GOLDEN").is_some() {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, &text).unwrap();
        }
        let expected = std::fs::read_to_string(&path).unwrap_or_else(|_| {
            panic!(
                "missing {}; run with MELISSA_UPDATE_GOLDEN=1",
                path.display()
            )
        });
        assert_eq!(text, expected, "golden {name} differs; review and update");
    }

    #[test]
    fn nextcloud_renders_to_the_golden_objects() {
        let m = nextcloud();
        let config = m.resolve_config(&serde_json::Map::new()).unwrap();
        golden(
            "nextcloud",
            &as_json(&render(&m, &config, "melissa.home.arpa")),
        );
    }

    #[test]
    fn overrides_and_domain_reach_the_pod_and_ingress() {
        let m = nextcloud();
        let overrides = json!({"admin_user": "owner", "upload_limit": "2G"});
        let config = m.resolve_config(overrides.as_object().unwrap()).unwrap();
        let o = render(&m, &config, "home.example.com");
        let pod = o.deployment.spec.template.spec.as_ref().unwrap();
        let env = pod.containers[0].env.as_ref().unwrap();
        let get = |n: &str| env.iter().find(|e| e.name == n).unwrap();
        assert_eq!(get("NEXTCLOUD_ADMIN_USER").value.as_deref(), Some("owner"));
        assert_eq!(get("PHP_UPLOAD_LIMIT").value.as_deref(), Some("2G"));
        assert_eq!(
            get("NEXTCLOUD_TRUSTED_DOMAINS").value.as_deref(),
            Some("nextcloud.home.example.com")
        );
        // The password is only a reference to the Secret, never a literal in the pod spec.
        let pw = get("NEXTCLOUD_ADMIN_PASSWORD");
        assert!(pw.value.is_none());
        let key = pw
            .value_from
            .as_ref()
            .unwrap()
            .secret_key_ref
            .as_ref()
            .unwrap();
        assert_eq!(
            (key.name.as_str(), key.key.as_str()),
            ("nextcloud-secrets", "admin_password")
        );
        let rule = &o.ingress.unwrap().spec.unwrap().rules.unwrap()[0];
        assert_eq!(rule.host.as_deref(), Some("nextcloud.home.example.com"));
        let ann = o.deployment.metadata.annotations.unwrap();
        let cfg: Value = serde_json::from_str(&ann[CONFIG_ANNOTATION]).unwrap();
        assert_eq!(cfg["admin_user"], "owner");
        assert!(cfg.get("admin_password").is_none());
    }

    #[test]
    fn namespace_and_binding_are_locked_down() {
        let m = nextcloud();
        let o = render(
            &m,
            &m.resolve_config(&serde_json::Map::new()).unwrap(),
            "x.test",
        );
        let labels = o.namespace.metadata.labels.unwrap();
        assert_eq!(labels[APP_LABEL], "nextcloud");
        assert_eq!(labels["pod-security.kubernetes.io/enforce"], "baseline");
        assert_eq!(o.namespace.metadata.name.as_deref(), Some("app-nextcloud"));
        assert_eq!(o.role_binding.role_ref.name, WORKLOAD_ROLE);
        assert_eq!(
            o.role_binding.metadata.namespace.as_deref(),
            Some("app-nextcloud")
        );
        let pod = o.deployment.spec.template.spec.unwrap();
        assert_eq!(pod.automount_service_account_token, Some(false));
        assert!(pod.host_network.is_none() && pod.host_pid.is_none());
        assert!(pod.containers.iter().all(|c| c.security_context.is_none()));
        assert_eq!(
            o.service.unwrap().spec.unwrap().type_.as_deref(),
            Some("ClusterIP")
        );
    }

    #[test]
    fn secret_object_carries_only_the_given_values() {
        let m = nextcloud();
        let o = render(
            &m,
            &m.resolve_config(&serde_json::Map::new()).unwrap(),
            "x.test",
        );
        let plan = o.secret.unwrap();
        assert_eq!(
            plan.keys,
            BTreeMap::from([("admin_password".to_string(), 32)])
        );
        let s = secret_object(
            &plan,
            BTreeMap::from([("admin_password".into(), "pw".into())]),
        );
        assert_eq!(s.metadata.name.as_deref(), Some("nextcloud-secrets"));
        assert_eq!(s.string_data.unwrap()["admin_password"], "pw");
    }

    #[test]
    fn label_values_are_sanitized() {
        assert_eq!(label_value("34.0.6"), "34.0.6");
        assert_eq!(label_value("1.0 (beta)"), "1.0__beta");
        assert_eq!(label_value(&"x".repeat(80)).len(), 63);
    }
}
